records.Body:
/**
 * @description Handler class for COLA (Cost of Living Adjustment) uplift calculations
 *              on QuoteLineItem records. Applies COLA percentage based on a three-tier hierarchy:
 *              1. Line Override - Manual edit on QuoteLineItem (highest priority)
 *              2. Contract Override - Active Contract COLA override (if valid)
 *              3. CMDT Lookup - Default from COLA_Uplift_Rules__mdt by Solution Category
 * @author Claude/Fortra
 * @date December 2024
 */
public with sharing class COLAUpliftHandler {

    /**
     * @description Handles Before Insert trigger context. Applies COLA uplift to renewal quote lines.
     * @param newItems List of new QuoteLineItem records being inserted
     */
    public static void handleBeforeInsert(List<QuoteLineItem> newItems) {
        if (newItems == null || newItems.isEmpty()) {
            return;
        }

        // Collect QuoteActionIds from the new items
        Set<Id> quoteActionIds = new Set<Id>();
        for (QuoteLineItem qli : newItems) {
            if (qli.QuoteActionId != null) {
                quoteActionIds.add(qli.QuoteActionId);
            }
        }

        if (quoteActionIds.isEmpty()) {
            return;
        }

        // Query QuoteActions with Asset and Product data for renewals only
        Map<Id, QuoteAction> quoteActionMap = new Map<Id, QuoteAction>([
            SELECT Id, Type, SourceAssetId, SourceAsset.Price, SourceAsset.Product2Id,
                   SourceAsset.Product2.Solution_Category__c
            FROM QuoteAction
            WHERE Id IN :quoteActionIds
            AND Type = 'Renew'
        ]);

        if (quoteActionMap.isEmpty()) {
            return;
        }

        // Populate COLA fields for renewal quote lines
        populateCOLAFields(newItems, quoteActionMap);
    }

    /**
     * @description Handles Before Update trigger context. Recalculates price when COLA % is overridden.
     * @param newItems List of updated QuoteLineItem records
     * @param oldMap Map of old QuoteLineItem records by Id
     */
    public static void handleBeforeUpdate(List<QuoteLineItem> newItems, Map<Id, QuoteLineItem> oldMap) {
        if (newItems == null || newItems.isEmpty() || oldMap == null) {
            return;
        }

        // Load CMDT rules once (lazy) for COLA_Source sync
        Map<String, COLA_Uplift_Rules__mdt> colaRulesMap = null;

        List<QuoteLineItem> changedItems = new List<QuoteLineItem>();

        for (QuoteLineItem qli : newItems) {
            QuoteLineItem oldQli = oldMap.get(qli.Id);
            if (oldQli == null) continue;

            // Year-1 Line Override: a direct user edit to COLA_Uplift_Percent__c
            // (new non-null and changed from the prior value — INCLUDING a
            // null->value edit on a legacy/partially-hydrated line) that diverges
            // from EVERY active system value must be promoted to 'Line Override'
            // BEFORE the system-source sync below, or that sync resets it back to
            // the CMDT rate. The old value is intentionally NOT required to be
            // non-null: isManualLineOverride already rejects system values
            // (CMDT/MyCAP), so a programmatic null->CMDT population is not
            // promoted, while a genuine null->override edit is. This is the
            // single-year analogue of the outyear override detection further down
            // — a 1-year renewal has no outyear field to trip that path, so
            // without this a year-1 override can never stick.
            if (qli.COLA_Source__c != 'Line Override'
                && qli.COLA_Source__c != 'Contract Override'
                && qli.COLA_Uplift_Percent__c != null
                && qli.COLA_Uplift_Percent__c != oldQli.COLA_Uplift_Percent__c
                && qli.COLA_Solution_Category__c != null) {
                if (colaRulesMap == null) {
                    colaRulesMap = getCOLARulesMap();
                }
                COLA_Uplift_Rules__mdt y1Rule = colaRulesMap.get(qli.COLA_Solution_Category__c);
                if (y1Rule != null && y1Rule.Default_Uplift_Percent__c != null) {
                    // Use the SINGLE shared override predicate (isManualLineOverride),
                    // matching the prehook's year-1 detection. The year-1 system value
                    // is the CMDT default ONLY — MyCAP is an OUTYEAR concept
                    // (COLA_Outyear_Uplift_Percent__c), never a year-1 value (confirmed
                    // by live data: 0 of 7 real 'MyCAP Default' lines carry the MyCAP
                    // value in year-1). MyCAP is therefore passed as null here: a year-1
                    // edit equal to the MyCAP rate (e.g. 3%) is a GENUINE manual override
                    // and must stick. Contract Override is covered by the COLA_Source__c
                    // != 'Contract Override' guard above, so it is null here too.
                    if (isManualLineOverride(qli.COLA_Uplift_Percent__c, y1Rule.Default_Uplift_Percent__c, null, null)) {
                        qli.Is_COLA_Overridden__c = true;
                        qli.COLA_Source__c = 'Line Override';
                        qli.COLA_Modified_By__c = UserInfo.getUserId();
                        qli.COLA_Modified_Date__c = DateTime.now();
                    }
                }
            }

            // Sync COLA% to CMDT default when COLA_Source is a system source
            // (MyCAP Default or CMDT Lookup) and COLA% doesn't already match.
            // The prehook uses the CMDT rate for year-1 pricing but can't
            // write COLA_Uplift_Percent__c (context-only attribute), so the
            // trigger syncs it on every pricing write-back.
            // Contract Override and Line Override are excluded: their percent
            // comes from the Contract record / user edit, not CMDT.
            // NOTE: a MyCAP-source year-1 value normalizing to CMDT here is BY
            // DESIGN, not a bug — MyCAP is an OUTYEAR concept
            // (COLA_Outyear_Uplift_Percent__c). Confirmed by live data: 0 of 7
            // real 'MyCAP Default' lines on fortrauat carry the MyCAP value in
            // year-1; all carry the CMDT default. The year-1 override predicate
            // above only prevents a coincidental year-1==MyCAP value from being
            // mislabeled a manual override; this block then normalizes it to CMDT.
            if (qli.COLA_Source__c != null
                && qli.COLA_Source__c != 'Line Override'
                && qli.COLA_Source__c != 'Contract Override'
                && qli.COLA_Solution_Category__c != null) {
                if (colaRulesMap == null) {
                    colaRulesMap = getCOLARulesMap();
                }
                COLA_Uplift_Rules__mdt rule = colaRulesMap.get(qli.COLA_Solution_Category__c);
                if (rule != null && rule.Default_Uplift_Percent__c != null
                    && qli.COLA_Uplift_Percent__c != rule.Default_Uplift_Percent__c) {
                    qli.COLA_Uplift_Percent__c = rule.Default_Uplift_Percent__c;
                    qli.Default_COLA_Uplift_Percent__c = rule.Default_Uplift_Percent__c;
                    qli.Is_COLA_Overridden__c = false;
                }
            }

            // Outyear uplift defaulting — only fires for sources where the
            // prehook's multi-year detection already gated (Contract Override
            // and MyCAP Default are both multi-year-relevant). Cannot rely on
            // PricingTermUnit because it is read-only and gets stripped from
            // Trigger.new; PricingTermCount is readable and > 1 is a
            // reliable multi-term signal. Line Override skipped to respect
            // user edits; CMDT Lookup skipped because single-year has no
            // outyear.
            if ((qli.COLA_Source__c == 'Contract Override'
                    || qli.COLA_Source__c == 'MyCAP Default')
                && qli.PricingTermCount != null && qli.PricingTermCount > 1
                && qli.COLA_Outyear_Uplift_Percent__c == null) {
                MyCAP_Rules__mdt mycapRule = MyCAP_Rules__mdt.getInstance('Global');
                if (mycapRule != null && mycapRule.Is_Active__c == true) {
                    qli.COLA_Outyear_Uplift_Percent__c = mycapRule.Default_Out_Year_Uplift_Percent__c != null
                        ? mycapRule.Default_Out_Year_Uplift_Percent__c : 3;
                }
            }

            // Check if COLA percentage was changed (by user or by sync above)
            if (qli.COLA_Uplift_Percent__c != null &&
                qli.COLA_Uplift_Percent__c != oldQli.COLA_Uplift_Percent__c &&
                qli.Pre_COLA_Price__c != null) {

                changedItems.add(qli);
            }

            // Flag override when outyear percent is changed by user.
            // Requires BOTH old and new to be non-null so the programmatic
            // null-to-MyCAP-default population above is not mistaken for a
            // user edit. Actual user edits are either non-null→non-null or
            // user explicitly nulling the field (not covered here).
            if (qli.COLA_Outyear_Uplift_Percent__c != null
                && oldQli.COLA_Outyear_Uplift_Percent__c != null
                && qli.COLA_Outyear_Uplift_Percent__c != oldQli.COLA_Outyear_Uplift_Percent__c) {
                MyCAP_Rules__mdt mr = MyCAP_Rules__mdt.getInstance('Global');
                // Active-gate MyCAP exactly like the year-1 block and the prehook:
                // an inactive/missing MyCAP rule is NOT a system value (null), so a
                // user's outyear edit must read as a real override rather than be
                // mistaken for the disabled default. Reuses the one shared predicate
                // (no CMDT or Contract source applies to the outyear value, so those
                // arguments are null).
                Decimal mycapDflt = (mr != null && mr.Is_Active__c == true)
                    ? (mr.Default_Out_Year_Uplift_Percent__c != null ? mr.Default_Out_Year_Uplift_Percent__c : 3)
                    : null;
                Boolean outyearOverridden = isManualLineOverride(qli.COLA_Outyear_Uplift_Percent__c, null, mycapDflt, null);
                // Compare year-1 against CMDT lookup (not stale Default field)
                if (colaRulesMap == null) { colaRulesMap = getCOLARulesMap(); }
                Boolean year1Overridden = false;
                if (qli.COLA_Solution_Category__c != null) {
                    COLA_Uplift_Rules__mdt catRule = colaRulesMap.get(qli.COLA_Solution_Category__c);
                    if (catRule != null && catRule.Default_Uplift_Percent__c != null) {
                        year1Overridden = (qli.COLA_Uplift_Percent__c != catRule.Default_Uplift_Percent__c);
                    }
                }
                qli.Is_COLA_Overridden__c = outyearOverridden || year1Overridden;
                if (qli.Is_COLA_Overridden__c) {
                    qli.COLA_Source__c = 'Line Override';
                    qli.COLA_Modified_By__c = UserInfo.getUserId();
                    qli.COLA_Modified_Date__c = DateTime.now();
                } else {
                    qli.COLA_Source__c = 'MyCAP Default';
                }
            }
        }

        if (!changedItems.isEmpty()) {
            recalculateCOLAPrice(changedItems);
        }
    }

    /**
     * @description The single authoritative "is this a manual Line Override?" predicate,
     *              shared by this trigger handler AND COLAUpliftPrehook so the two can
     *              never drift. A percent is a manual override only when it is non-null
     *              and differs from EVERY known system source: the CMDT default, the
     *              MyCAP default, and the Contract Override. A null system value means
     *              "no such system source" and is skipped (matches the prehook, where an
     *              inactive/missing MyCAP rule yields a null mycapDefaultPct).
     * @param pct            The line's COLA_Uplift_Percent__c (the value under test).
     * @param cmdtDefaultPct The CMDT (COLA_Uplift_Rules__mdt) default for the category.
     * @param mycapDefaultPct The active MyCAP default, or null if MyCAP is inactive/missing.
     * @param contractPct    The applicable Contract Override percent, or null if none.
     * @return true when pct represents a genuine manual edit, false when it matches a system source.
     */
    public static Boolean isManualLineOverride(Decimal pct, Decimal cmdtDefaultPct, Decimal mycapDefaultPct, Decimal contractPct) {
        return pct != null
            && pct != cmdtDefaultPct
            && (mycapDefaultPct == null || pct != mycapDefaultPct)
            && (contractPct == null || pct != contractPct);
    }

    /**
     * @description Populates COLA fields on quote line items for renewal transactions.
     *              Uses three-tier override hierarchy: Line Override > Contract Override > CMDT Lookup.
     *              Thin wrapper that resolves the Contract-override map (which performs the
     *              AssetContractRelationship query) and delegates the per-line tier logic to the
     *              testable core below.
     * @param items List of QuoteLineItem records to process
     * @param quoteActions Map of QuoteAction records with Asset data
     */
    private static void populateCOLAFields(List<QuoteLineItem> items, Map<Id, QuoteAction> quoteActions) {
        // Collect Asset IDs to query Contract overrides
        Set<Id> assetIds = new Set<Id>();
        for (QuoteAction qa : quoteActions.values()) {
            if (qa.SourceAssetId != null) {
                assetIds.add(qa.SourceAssetId);
            }
        }

        // Get Contract overrides for Assets via AssetContractRelationship.
        // NOTE: getContractOverrides delegates to AssetContractQueryHelper.queryAssetContracts,
        // which runs the live AssetContractRelationship SOQL inside its own try/catch.
        Map<Id, ContractOverride> contractOverridesByAssetId = getContractOverrides(assetIds);

        populateCOLAFields(items, quoteActions, contractOverridesByAssetId);
    }

    /**
     * @description Testable core of populateCOLAFields: applies the three-tier override hierarchy to
     *              each renewal line given a PRE-RESOLVED Contract-override map. Extracting the map as a
     *              parameter lets tests exercise the Tier-2 (Contract Override) branch with an in-memory
     *              override map, because the underlying AssetContractRelationship cannot be inserted in a
     *              test on this org (the linked Asset needs platform-owned HasLifecycleManagement=true).
     *              No SOQL on the line loop apart from the CMDT rules lookup. Behavior is identical to the
     *              prior inline implementation.
     * @param items List of QuoteLineItem records to process
     * @param quoteActions Map of QuoteAction records with Asset data
     * @param contractOverridesByAssetId Resolved Tier-2 overrides keyed by SourceAssetId
     */
    @TestVisible
    private static void populateCOLAFields(
        List<QuoteLineItem> items,
        Map<Id, QuoteAction> quoteActions,
        Map<Id, ContractOverride> contractOverridesByAssetId
    ) {
        // Get COLA rules from Custom Metadata
        Map<String, COLA_Uplift_Rules__mdt> colaRulesMap = getCOLARulesMap();

        // Process each quote line item
        for (QuoteLineItem qli : items) {
            if (qli.QuoteActionId == null) {
                continue;
            }

            QuoteAction qa = quoteActions.get(qli.QuoteActionId);
            if (qa == null || qa.SourceAsset == null) {
                continue;
            }

            // Get the Asset price as base
            Decimal assetPrice = qa.SourceAsset.Price;
            if (assetPrice == null) {
                continue;
            }

            // Get Solution Category directly from Product2
            String solutionCategory = null;
            if (qa.SourceAsset.Product2 != null) {
                solutionCategory = qa.SourceAsset.Product2.Solution_Category__c;
            }

            // Initialize COLA values
            Decimal colaPercent = 0;
            String colaSource = 'CMDT Lookup';

            // TIER 2: Check for Contract-level override first
            if (qa.SourceAssetId != null && contractOverridesByAssetId.containsKey(qa.SourceAssetId)) {
                ContractOverride contractOverride = contractOverridesByAssetId.get(qa.SourceAssetId);
                if (contractOverride.isValid) {
                    colaPercent = contractOverride.overridePercent;
                    colaSource = 'Contract Override';
                }
            }

            // TIER 3: If no valid Contract override, use CMDT lookup
            if (colaSource == 'CMDT Lookup') {
                if (String.isNotBlank(solutionCategory) && colaRulesMap.containsKey(solutionCategory)) {
                    COLA_Uplift_Rules__mdt rule = colaRulesMap.get(solutionCategory);
                    if (rule.Is_Active__c) {
                        colaPercent = rule.Default_Uplift_Percent__c != null ? rule.Default_Uplift_Percent__c : 0;
                    }
                }
            }

            // Calculate new price with COLA
            Decimal newPrice = assetPrice * (1 + (colaPercent / 100));

            // Populate COLA fields
            qli.UnitPrice = newPrice;
            qli.Pre_COLA_Price__c = assetPrice;
            qli.COLA_Uplift_Percent__c = colaPercent;
            qli.Default_COLA_Uplift_Percent__c = colaPercent;
            qli.COLA_Solution_Category__c = solutionCategory;
            qli.COLA_Applied_Date__c = DateTime.now();
            qli.Is_COLA_Overridden__c = false;
            qli.COLA_Source__c = colaSource;
        }
    }

    /**
     * @description Recalculates UnitPrice when COLA percentage is overridden by user
     * @param changedItems List of QuoteLineItem records with changed COLA percentage
     */
    private static void recalculateCOLAPrice(List<QuoteLineItem> changedItems) {
        for (QuoteLineItem qli : changedItems) {
            if (qli.Pre_COLA_Price__c != null && qli.COLA_Uplift_Percent__c != null) {
                // Recalculate price using Pre-COLA price as base
                Decimal newPrice = qli.Pre_COLA_Price__c * (1 + (qli.COLA_Uplift_Percent__c / 100));
                qli.UnitPrice = newPrice;

                // Update audit fields
                qli.COLA_Modified_By__c = UserInfo.getUserId();
                qli.COLA_Modified_Date__c = DateTime.now();

                // Set override flag and source (Tier 1 - Line Override takes priority).
                // Do NOT re-derive the classification for a line already promoted to
                // Line Override by the predicate-based blocks above (year-1 / outyear):
                // recomputing from the possibly-stale Default_COLA_Uplift_Percent__c can
                // wrongly clear a genuine override — e.g. a null-old / legacy line whose
                // stale Default happens to equal the user's value while the active CMDT
                // rate differs. Those blocks own Is_COLA_Overridden__c / COLA_Source__c.
                if (qli.COLA_Source__c != 'Line Override') {
                    qli.Is_COLA_Overridden__c = (qli.COLA_Uplift_Percent__c != qli.Default_COLA_Uplift_Percent__c);
                    if (qli.Is_COLA_Overridden__c) {
                        qli.COLA_Source__c = 'Line Override';
                    }
                }
            }
        }
    }

    /**
     * @description Gets COLA rules from Custom Metadata Type, indexed by Solution Category
     * @return Map of COLA rules keyed by Solution Category name
     */
    private static Map<String, COLA_Uplift_Rules__mdt> getCOLARulesMap() {
        Map<String, COLA_Uplift_Rules__mdt> rulesMap = new Map<String, COLA_Uplift_Rules__mdt>();

        for (COLA_Uplift_Rules__mdt rule : [
            SELECT MasterLabel, Solution_Category__c, Default_Uplift_Percent__c, Is_Active__c,
                   Effective_Start_Date__c, Effective_End_Date__c, Description__c
            FROM COLA_Uplift_Rules__mdt
            WHERE Is_Active__c = true
        ]) {
            if (String.isNotBlank(rule.Solution_Category__c)) {
                // Check effective dates if specified
                Date today = Date.today();
                Boolean isEffective = true;

                if (rule.Effective_Start_Date__c != null && today < rule.Effective_Start_Date__c) {
                    isEffective = false;
                }
                if (rule.Effective_End_Date__c != null && today > rule.Effective_End_Date__c) {
                    isEffective = false;
                }

                if (isEffective) {
                    rulesMap.put(rule.Solution_Category__c, rule);
                }
            }
        }

        return rulesMap;
    }

    /**
     * @description Gets Contract-level COLA overrides for Assets via AssetContractRelationship
     * @param assetIds Set of Asset IDs to query
     * @return Map of ContractOverride wrappers keyed by Asset Id
     */
    private static Map<Id, ContractOverride> getContractOverrides(Set<Id> assetIds) {
        if (assetIds == null || assetIds.isEmpty()) {
            return new Map<Id, ContractOverride>();
        }

        // Query AssetContractRelationship using elevated access helper.
        // This is necessary because Revenue Cloud objects may not be accessible
        // via dynamic SOQL in trigger context with sharing enforcement.
        // NOTE: queryAssetContracts runs the live AssetContractRelationship + Contract
        // SOQL inside its own try/catch; this method only transforms its rows.
        List<AssetContractQueryHelper.AssetContractData> contractDataList =
            AssetContractQueryHelper.queryAssetContracts(assetIds);

        return buildContractOverrideMap(contractDataList);
    }

    /**
     * @description Builds the keyed-by-Asset Contract-override map from already-queried
     *              AssetContractData rows, applying the persist-date validity logic. Pure in-memory
     *              transform (no SOQL/DML) so tests can drive the Tier-2 validity branches with
     *              in-memory AssetContractData rows -- the underlying AssetContractRelationship cannot
     *              be inserted in a test on this org (the linked Asset needs platform-owned
     *              HasLifecycleManagement=true). The live path delegates here unchanged.
     * @param contractDataList AssetContractData rows from AssetContractQueryHelper.queryAssetContracts
     * @return Map of valid ContractOverride wrappers keyed by Asset Id
     */
    @TestVisible
    private static Map<Id, ContractOverride> buildContractOverrideMap(
        List<AssetContractQueryHelper.AssetContractData> contractDataList
    ) {
        Map<Id, ContractOverride> overrideMap = new Map<Id, ContractOverride>();
        if (contractDataList == null) {
            return overrideMap;
        }

        Date today = Date.today();

        for (AssetContractQueryHelper.AssetContractData contractData : contractDataList) {
            // Skip if no COLA override set
            if (contractData.colaOverridePercent == null) {
                continue;
            }

            // Check if override is valid based on persist date logic
            Boolean isValid = false;
            Date persistUntil = contractData.colaPersistUntil;

            if (persistUntil == null) {
                // Null persist date = one-time use, valid for next renewal
                isValid = true;
            } else if (persistUntil >= today) {
                // Future persist date = valid for renewals until that date
                isValid = true;
            }
            // Past persist date = expired, not valid (isValid remains false)

            if (isValid) {
                ContractOverride colaOverride = new ContractOverride();
                colaOverride.contractId = contractData.contractId;
                colaOverride.overridePercent = contractData.colaOverridePercent;
                colaOverride.persistUntil = persistUntil;
                colaOverride.isValid = true;

                // Only use the first valid activated Contract per Asset
                // (In practice, there should only be one active Contract per Asset)
                if (!overrideMap.containsKey(contractData.assetId)) {
                    overrideMap.put(contractData.assetId, colaOverride);
                }
            }
        }

        return overrideMap;
    }

    /**
     * @description Wrapper class for Contract COLA override information
     */
    @TestVisible
    private class ContractOverride {
        public Id contractId;
        public Decimal overridePercent;
        public Date persistUntil;
        public Boolean isValid;
    }

}

/**
 * @description Normalizes asset-renewed Renewal Maintenance lines so billing Quantity
 *              matches the source asset entitlement. Platform Asset Renew often creates
 *              No Change lines with Quantity 0 while StartQuantity/EndQuantity reflect
 *              the asset; DPP and persist require billing Quantity from the asset.
 *
 *              Runs in a Queueable after QuoteLineItem insert so updates do not conflict
 *              with Place Sales Transaction persist during Asset Renew.
 */
public with sharing class RenewalAssetQuantityHandler {

    public static final String QUOTE_ACTION_RENEW = 'Renew';
    public static final String QUOTE_ACTION_NO_CHANGE = 'No Change';
    public static final String PRODUCT_TYPE_RENEWAL_MAINTENANCE =
        RenewalQuoteLineHandler.PRODUCT_TYPE_RENEWAL_MAINTENANCE;

    /**
     * @description Called from QuoteLineItem after insert. Defers normalization until PST completes.
     */
    public static void enqueueQuantityNormalization(List<QuoteLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        Set<Id> quoteIds = collectQuoteIds(newLines);
        if (quoteIds.isEmpty()) {
            return;
        }

        if (Test.isRunningTest()) {
            applyAssetQuantitiesForQuotes(quoteIds);
            return;
        }

        System.enqueueJob(new RenewalAssetQuantityQueueable(quoteIds));
    }

    /**
     * @description Direct entry for tests and manual invocation.
     */
    public static void applyAssetQuantitiesForQuotes(Set<Id> quoteIds) {
        if (quoteIds == null || quoteIds.isEmpty()) {
            return;
        }

        Set<Id> renewalQuoteIds = resolveRenewalQuoteIds(quoteIds);
        if (renewalQuoteIds.isEmpty()) {
            return;
        }

        List<QuoteLineItem> candidates = [
            SELECT Id, QuoteId, Quantity, StartQuantity, EndQuantity, QuoteActionId,
                   QuoteAction.Type, QuoteAction.SourceAssetId, QuoteAction.SourceAsset.Quantity,
                   Fortra_Product_Type__c
            FROM QuoteLineItem
            WHERE QuoteId IN :renewalQuoteIds
              AND Fortra_Product_Type__c = :PRODUCT_TYPE_RENEWAL_MAINTENANCE
              AND QuoteActionId != null
              AND (Quantity = null OR Quantity <= 0)
        ];

        if (candidates.isEmpty()) {
            return;
        }

        applyNormalizationUpdates(buildNormalizationUpdates(candidates));
    }

    @TestVisible
    private static NormalizationUpdates buildNormalizationUpdates(List<QuoteLineItem> candidates) {
        NormalizationUpdates updates = new NormalizationUpdates();

        if (candidates == null || candidates.isEmpty()) {
            return updates;
        }

        for (QuoteLineItem qli : candidates) {
            Decimal sourceQuantity = resolveSourceQuantity(qli);
            if (!needsQuantityNormalization(qli, sourceQuantity)) {
                continue;
            }

            String actionType = qli.QuoteAction?.Type;
            if (actionType == QUOTE_ACTION_NO_CHANGE) {
                updates.quoteActionsById.put(
                    qli.QuoteActionId,
                    new QuoteAction(Id = qli.QuoteActionId, Type = QUOTE_ACTION_RENEW)
                );
            } else if (actionType != QUOTE_ACTION_RENEW) {
                continue;
            }

            updates.linesToUpdate.add(new QuoteLineItem(
                Id = qli.Id,
                Quantity = sourceQuantity,
                StartQuantity = 0
            ));
        }

        return updates;
    }

    private static void applyNormalizationUpdates(NormalizationUpdates updates) {
        if (updates == null) {
            return;
        }
        if (!updates.quoteActionsById.isEmpty()) {
            update updates.quoteActionsById.values();
        }
        if (!updates.linesToUpdate.isEmpty()) {
            update updates.linesToUpdate;
        }
    }

    @TestVisible
    private class NormalizationUpdates {
        public Map<Id, QuoteAction> quoteActionsById { get; private set; }
        public List<QuoteLineItem> linesToUpdate { get; private set; }

        private NormalizationUpdates() {
            quoteActionsById = new Map<Id, QuoteAction>();
            linesToUpdate = new List<QuoteLineItem>();
        }
    }

    @TestVisible
    private static Boolean needsQuantityNormalization(QuoteLineItem qli, Decimal sourceQuantity) {
        if (qli == null || sourceQuantity == null || sourceQuantity <= 0) {
            return false;
        }
        if (qli.Fortra_Product_Type__c != PRODUCT_TYPE_RENEWAL_MAINTENANCE) {
            return false;
        }
        if (qli.QuoteActionId == null) {
            return false;
        }

        Decimal quantity = qli.Quantity == null ? 0 : qli.Quantity;
        return quantity <= 0;
    }

    @TestVisible
    private static Decimal resolveSourceQuantity(QuoteLineItem qli) {
        if (qli == null) {
            return null;
        }

        return resolveSourceQuantity(
            qli.QuoteAction?.SourceAsset?.Quantity,
            qli.EndQuantity,
            qli.StartQuantity
        );
    }

    @TestVisible
    private static Decimal resolveSourceQuantity(
        Decimal assetQuantity,
        Decimal endQuantity,
        Decimal startQuantity
    ) {
        if (assetQuantity != null && assetQuantity > 0) {
            return assetQuantity;
        }
        if (endQuantity != null && endQuantity > 0) {
            return endQuantity;
        }
        if (startQuantity != null && startQuantity > 0) {
            return startQuantity;
        }
        return null;
    }

    private static Set<Id> collectQuoteIds(List<QuoteLineItem> lines) {
        Set<Id> quoteIds = new Set<Id>();
        for (QuoteLineItem line : lines) {
            if (line.QuoteId != null) {
                quoteIds.add(line.QuoteId);
            }
        }
        return quoteIds;
    }

    @TestVisible
    private static Set<Id> resolveRenewalQuoteIds(Set<Id> quoteIds) {
        Set<Id> renewalQuoteIds = new Set<Id>();
        for (Quote quote : [
            SELECT Id
            FROM Quote
            WHERE Id IN :quoteIds
              AND (
                  OriginalActionType = :QuoteRenewalTypeHandler.ORIGINAL_ACTION_RENEW
                  OR Quote_Type__c = :QuoteRenewalTypeHandler.QUOTE_TYPE_RENEWAL
              )
        ]) {
            renewalQuoteIds.add(quote.Id);
        }
        return renewalQuoteIds;
    }
}

/**
 * @description Applies COLA uplift net price to renewal maintenance quote lines when DPP
 *              leaves NetUnitPrice at zero. Updates pricing context before persist.
 */
public with sharing class RenewalMaintenancePricingService {

    private static final String CONTEXT_DEFINITION_NAME = 'SalesTransactionContextExt_v2';

    // ---------------------------------------------------------------------
    // Test seams. These are inert in production: every guard additionally
    // requires Test.isRunningTest(), and each override defaults to null, so a
    // production execution takes the exact same Context.IndustriesContext call
    // path as before. They exist only so a unit test can substitute a fabricated
    // queryTags response / context id for the live pricing-context I/O, which
    // throws (NoDataFoundException / UnexpectedException gack) outside a real
    // pricing transaction and is otherwise unreachable from an Apex test.
    @TestVisible
    private static Map<String, Object> testQueryTagsResponse;
    @TestVisible
    private static String testContextIdOverride;

    public class RepriceRequest {
        @InvocableVariable(required=true label='Quote Id')
        public String quoteId;

        @InvocableVariable(label='Context Instance Id')
        public String contextInstanceId;

        @InvocableVariable(label='Finalize COLA Net After DPP')
        public Boolean finalizeAfterPricing;
    }

    public class RepriceResult {
        @InvocableVariable(label='COLA-Only Persist Completed')
        public Boolean colaOnlyPersistComplete;
    }

    @TestVisible
    public static Boolean usesColaOnlyReprice(Id quoteId) {
        if (quoteId == null) {
            return false;
        }

        List<Quote> quotes = [
            SELECT Id, Quote_Type__c, OriginalActionType
            FROM Quote
            WHERE Id = :quoteId
            LIMIT 1
        ];
        if (quotes.isEmpty()) {
            return false;
        }

        List<QuoteLineItem> lines = [
            SELECT Id, Fortra_Product_Type__c, Product2.Fortra_Product_Type__c,
                   Base_Price__c, NetUnitPrice, TotalPrice
            FROM QuoteLineItem
            WHERE QuoteId = :quoteId
        ];

        return usesColaOnlyRepriceForLines(quotes[0], lines);
    }

    @TestVisible
    public static Boolean usesColaOnlyRepriceForLines(Quote quote, List<QuoteLineItem> lines) {
        if (quote == null || lines == null || lines.isEmpty()) {
            return false;
        }

        Boolean isRenewal = quote.Quote_Type__c == QuoteRenewalTypeHandler.QUOTE_TYPE_RENEWAL
            || quote.OriginalActionType == QuoteRenewalTypeHandler.ORIGINAL_ACTION_RENEW;
        if (!isRenewal) {
            return false;
        }

        Boolean hasRenewalMaintenance = false;
        for (QuoteLineItem qli : lines) {
            String productType = qli.Fortra_Product_Type__c != null
                ? qli.Fortra_Product_Type__c
                : qli.Product2?.Fortra_Product_Type__c;

            if (productType == 'Renewal Maintenance') {
                hasRenewalMaintenance = qli.Base_Price__c != null && qli.Base_Price__c > 0;
                continue;
            }

            if (productType == 'Perpetual' || productType == 'Software') {
                return false;
            }

            if (qli.TotalPrice != null && qli.TotalPrice > 0) {
                return false;
            }
        }

        return hasRenewalMaintenance;
    }

    @InvocableMethod(
        label='Apply Renewal Maintenance COLA Net'
        description='Writes COLA net into pricing context for renewal maintenance lines before persist'
    )
    public static List<RepriceResult> applyRenewalMaintenanceNetPrices(List<RepriceRequest> requests) {
        List<RepriceResult> results = new List<RepriceResult>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        for (RepriceRequest request : requests) {
            RepriceResult result = new RepriceResult();
            result.colaOnlyPersistComplete = false;

            if (request == null || String.isBlank(request.quoteId)) {
                results.add(result);
                continue;
            }

            Id quoteId = Id.valueOf(request.quoteId);
            try {
                if (String.isNotBlank(request.contextInstanceId)) {
                    if (request.finalizeAfterPricing == true) {
                        applyColaNetFinalizeToContext(quoteId, request.contextInstanceId);
                    } else {
                        applyToContext(quoteId, request.contextInstanceId);
                    }
                } else {
                    finalizeRenewalMaintenanceAfterPricing(quoteId);
                }
            } catch (Exception e) {
                System.debug(LoggingLevel.WARN, 'Renewal maintenance COLA net skipped: ' + e.getMessage());
            }

            results.add(result);
        }

        return results;
    }

    /**
     * @description Rebuild context after main pricing persist and write COLA net for renewal maintenance.
     */
    public static void finalizeRenewalMaintenanceAfterPricing(Id quoteId) {
        if (quoteId == null) {
            return;
        }

        List<QuoteLineItem> candidates = queryRenewalMaintenanceCandidates(quoteId);
        if (candidates.isEmpty()) {
            return;
        }

        Context.IndustriesContext ctx = new Context.IndustriesContext();
        String contextId;
        if (Test.isRunningTest() && testContextIdOverride != null) {
            contextId = testContextIdOverride;
        } else {
            Map<String, Object> buildResult = ctx.buildContext(new Map<String, Object>{
                'contextDefinitionName' => CONTEXT_DEFINITION_NAME,
                'sourceRecordId' => quoteId
            });
            contextId = buildResult != null ? String.valueOf(buildResult.get('contextId')) : null;
        }
        if (String.isBlank(contextId)) {
            return;
        }

        applyToContext(quoteId, contextId);
        try {
            if (!(Test.isRunningTest() && testContextIdOverride != null)) {
                ctx.persistContext(new Map<String, Object>{ 'contextId' => contextId });
            }
        } catch (Exception e) {
            System.debug(LoggingLevel.WARN, 'Renewal maintenance context persist failed: ' + e.getMessage());
        }
    }

    @TestVisible
    private static void applyToContext(Id quoteId, String contextInstanceId) {
        List<QuoteLineItem> candidates = filterLinesNeedingColaNet(queryRenewalMaintenanceCandidates(quoteId));

        if (candidates.isEmpty()) {
            return;
        }

        Map<Id, Decimal> colaNetByLineId = new Map<Id, Decimal>();
        for (QuoteLineItem qli : candidates) {
            Decimal colaNet = computeColaNet(qli);
            if (colaNet != null && colaNet > 0) {
                colaNetByLineId.put(qli.Id, colaNet);
            }
        }

        if (colaNetByLineId.isEmpty()) {
            return;
        }

        Context.IndustriesContext ctx = new Context.IndustriesContext();
        Map<Id, Map<String, Object>> lineItemById = mapLineItemsById(
            queryLineItems(ctx, contextInstanceId)
        );

        System.debug(LoggingLevel.INFO, 'RenewalMaintenancePricingService updating ' + colaNetByLineId.size() + ' line(s)');

        List<Map<String, Object>> itemUpdates = new List<Map<String, Object>>();
        for (QuoteLineItem qli : candidates) {
            if (!colaNetByLineId.containsKey(qli.Id)) {
                continue;
            }

            Map<String, Object> lineItem = lineItemById.get(qli.Id);
            Object updatePath = resolveUpdatePath(lineItem, qli.QuoteId, qli.Id);
            if (updatePath == null) {
                continue;
            }

            Decimal colaNet = colaNetByLineId.get(qli.Id);

            itemUpdates.add(new Map<String, Object>{
                'nodePath' => new Map<String, Object>{ 'dataPath' => updatePath },
                'attributes' => new List<Map<String, Object>>{
                    new Map<String, Object>{ 'attributeName' => 'COLACalculatedPrice__c', 'attributeValue' => colaNet },
                    new Map<String, Object>{ 'attributeName' => 'InputUnitPrice', 'attributeValue' => colaNet },
                    new Map<String, Object>{ 'attributeName' => 'SalesTransactionActionType', 'attributeValue' => 'Renew' }
                }
            });
        }

        if (itemUpdates.isEmpty()) {
            return;
        }

        Map<String, Object> updateResult = (Test.isRunningTest() && testQueryTagsResponse != null)
            ? new Map<String, Object>{ 'isSuccess' => true }
            : ctx.updateContextAttributes(new Map<String, Object>{
                'contextId' => contextInstanceId,
                'nodePathAndAttributes' => itemUpdates
            });
        System.debug(LoggingLevel.INFO, 'RenewalMaintenancePricingService update result=' + updateResult);
    }

    /**
     * @description After DPP, write stamped COLA net into pricing context so persist
     *              does not keep a stale Last Transaction asset price on renewal maintenance.
     */
    @TestVisible
    private static void applyColaNetFinalizeToContext(Id quoteId, String contextInstanceId) {
        List<QuoteLineItem> candidates = filterLinesNeedingColaNet(queryRenewalMaintenanceCandidates(quoteId));
        if (candidates.isEmpty()) {
            return;
        }

        Context.IndustriesContext ctx = new Context.IndustriesContext();
        Map<Id, Map<String, Object>> lineItemById = mapLineItemsById(
            queryLineItems(ctx, contextInstanceId)
        );

        List<Map<String, Object>> itemUpdates = new List<Map<String, Object>>();
        for (QuoteLineItem qli : candidates) {
            Decimal colaNet = computeColaNet(qli);
            if (colaNet == null || colaNet <= 0) {
                continue;
            }

            Map<String, Object> lineItem = lineItemById.get(qli.Id);
            Object updatePath = resolveUpdatePath(lineItem, qli.QuoteId, qli.Id);
            if (updatePath == null) {
                continue;
            }

            Decimal lineTotal = resolveColaLineTotal(qli, colaNet);
            itemUpdates.add(new Map<String, Object>{
                'nodePath' => new Map<String, Object>{ 'dataPath' => updatePath },
                'attributes' => new List<Map<String, Object>>{
                    new Map<String, Object>{ 'attributeName' => 'COLACalculatedPrice__c', 'attributeValue' => colaNet },
                    new Map<String, Object>{ 'attributeName' => 'InputUnitPrice', 'attributeValue' => colaNet },
                    new Map<String, Object>{ 'attributeName' => 'UnitPrice', 'attributeValue' => colaNet },
                    new Map<String, Object>{ 'attributeName' => 'NetUnitPrice', 'attributeValue' => colaNet },
                    new Map<String, Object>{ 'attributeName' => 'NetTotalPrice', 'attributeValue' => lineTotal },
                    new Map<String, Object>{ 'attributeName' => 'TotalPrice', 'attributeValue' => lineTotal },
                    new Map<String, Object>{ 'attributeName' => 'PartnerUnitPrice', 'attributeValue' => colaNet }
                }
            });
        }

        if (itemUpdates.isEmpty()) {
            return;
        }

        System.debug(LoggingLevel.INFO, 'RenewalMaintenancePricingService finalizing ' + itemUpdates.size() + ' line(s)');

        Map<String, Object> updateResult = (Test.isRunningTest() && testQueryTagsResponse != null)
            ? new Map<String, Object>{ 'isSuccess' => true }
            : ctx.updateContextAttributes(new Map<String, Object>{
                'contextId' => contextInstanceId,
                'nodePathAndAttributes' => itemUpdates
            });
        System.debug(LoggingLevel.INFO, 'RenewalMaintenancePricingService finalize result=' + updateResult);
    }

    public static Decimal computeColaNet(QuoteLineItem qli) {
        if (qli == null || qli.Base_Price__c == null || qli.Base_Price__c <= 0) {
            return null;
        }

        Decimal priorPartner = qli.Prior_Partner_Discount__c != null ? qli.Prior_Partner_Discount__c : 0;
        Decimal priorDisc = resolveDiscretionaryDollars(qli);
        Decimal colaPercent = qli.COLA_Uplift_Percent__c != null ? qli.COLA_Uplift_Percent__c : 0;
        Decimal preColaNet = qli.Base_Price__c - priorPartner - priorDisc;

        if (preColaNet <= 0) {
            return null;
        }

        return (preColaNet * (1 + (colaPercent / 100))).setScale(2, RoundingMode.HALF_UP);
    }

    /**
     * @description Platform No Change asset-renew lines keep Quantity 0 on the record.
     *              Pricing context uses flat COLA net as the line total in that case.
     */
    @TestVisible
    public static Decimal resolveColaLineTotal(QuoteLineItem qli, Decimal colaNet) {
        if (colaNet == null) {
            return null;
        }
        Decimal quantity = qli != null ? qli.Quantity : null;
        if (quantity == null || quantity <= 0) {
            return colaNet;
        }
        return (colaNet * quantity).setScale(2, RoundingMode.HALF_UP);
    }

    @TestVisible
    private static List<QuoteLineItem> queryRenewalMaintenanceCandidates(Id quoteId) {
        return [
            SELECT Id, QuoteId, Base_Price__c, Prior_Partner_Discount__c, Prior_Discretionary_Discount__c,
                   PartnerDiscountPercent, Discount, COLA_Uplift_Percent__c, Quantity, NetUnitPrice
            FROM QuoteLineItem
            WHERE QuoteId = :quoteId
            AND Fortra_Product_Type__c = 'Renewal Maintenance'
            AND Base_Price__c > 0
        ];
    }

    @TestVisible
    private static List<QuoteLineItem> filterLinesNeedingColaNet(List<QuoteLineItem> lines) {
        List<QuoteLineItem> results = new List<QuoteLineItem>();
        if (lines == null || lines.isEmpty()) {
            return results;
        }

        for (QuoteLineItem qli : lines) {
            if (needsColaNetCorrection(qli)) {
                results.add(qli);
            }
        }
        return results;
    }

    @TestVisible
    private static Boolean needsColaNetCorrection(QuoteLineItem qli) {
        return needsColaNetCorrectionForValues(computeColaNet(qli), qli?.NetUnitPrice);
    }

    @TestVisible
    private static Boolean needsColaNetCorrectionForValues(Decimal colaNet, Decimal netUnitPrice) {
        if (colaNet == null || colaNet <= 0) {
            return false;
        }
        if (netUnitPrice == null || netUnitPrice == 0) {
            return true;
        }
        return netUnitPrice.setScale(2, RoundingMode.HALF_UP) != colaNet;
    }

    private static Decimal resolveDiscretionaryDollars(QuoteLineItem qli) {
        if (qli.Prior_Discretionary_Discount__c != null && qli.Prior_Discretionary_Discount__c > 0) {
            return qli.Prior_Discretionary_Discount__c;
        }
        if (qli.Discount == null || qli.Discount <= 0) {
            return 0;
        }

        Decimal priorPartner = qli.Prior_Partner_Discount__c != null ? qli.Prior_Partner_Discount__c : 0;
        return ((qli.Base_Price__c - priorPartner) * (qli.Discount / 100)).setScale(2, RoundingMode.HALF_UP);
    }

    private static Map<Id, Map<String, Object>> mapLineItemsById(List<Map<String, Object>> lineItems) {
        Map<Id, Map<String, Object>> lineItemById = new Map<Id, Map<String, Object>>();
        if (lineItems == null || lineItems.isEmpty()) {
            return lineItemById;
        }

        for (Map<String, Object> lineItem : lineItems) {
            Id lineItemId = getLineItemRecordId(lineItem);
            if (lineItemId != null) {
                lineItemById.put(lineItemId, lineItem);
            }
        }
        return lineItemById;
    }

    private static List<Map<String, Object>> queryLineItems(Context.IndustriesContext ctx, String contextInstanceId) {
        List<Map<String, Object>> lineItems = new List<Map<String, Object>>();
        Map<String, Object> apiResponse = (Test.isRunningTest() && testQueryTagsResponse != null)
            ? testQueryTagsResponse
            : ctx.queryTags(new Map<String, Object>{
                'contextId' => contextInstanceId,
                'tags' => new List<String>{ 'SalesTransactionItem' }
            });
        if (apiResponse == null) {
            return lineItems;
        }

        Map<String, Object> queryResult;
        if (apiResponse.containsKey('queryResult')) {
            Object qrObj = apiResponse.get('queryResult');
            queryResult = (qrObj instanceof Map<String, Object>) ? (Map<String, Object>) qrObj : null;
        } else if (apiResponse.containsKey('SalesTransactionItem')) {
            queryResult = apiResponse;
        } else {
            return lineItems;
        }

        if (queryResult == null || !queryResult.containsKey('SalesTransactionItem')) {
            return lineItems;
        }

        Object itemsObj = queryResult.get('SalesTransactionItem');
        List<Object> rawLineItems = (itemsObj instanceof List<Object>)
            ? (List<Object>) itemsObj
            : new List<Object>{ itemsObj };

        for (Object rawItem : rawLineItems) {
            if (!(rawItem instanceof Map<String, Object>)) {
                continue;
            }
            Map<String, Object> itemWrapper = (Map<String, Object>) rawItem;
            if (!itemWrapper.containsKey('tagValue')) {
                continue;
            }
            Object tagValue = itemWrapper.get('tagValue');
            if (!(tagValue instanceof Map<String, Object>)) {
                continue;
            }
            Map<String, Object> lineItemData = new Map<String, Object>();
            lineItemData.putAll((Map<String, Object>) tagValue);
            if (itemWrapper.containsKey('dataPath') && itemWrapper.get('dataPath') instanceof List<Object>) {
                List<Object> pathParts = (List<Object>) itemWrapper.get('dataPath');
                if (!pathParts.isEmpty()) {
                    lineItemData.put('_recordId', String.valueOf(pathParts[pathParts.size() - 1]));
                    List<Object> updatePath = pathParts.clone();
                    if (!updatePath.isEmpty()) {
                        updatePath.remove(0);
                    }
                    lineItemData.put('_updatePath', updatePath);
                }
            }
            lineItems.add(lineItemData);
        }

        return lineItems;
    }

    @TestVisible
    private static Object resolveUpdatePath(Map<String, Object> lineItem, Id quoteId, Id lineItemId) {
        if (lineItem != null && lineItem.get('_updatePath') != null) {
            return lineItem.get('_updatePath');
        }
        if (quoteId == null || lineItemId == null) {
            return null;
        }
        return new List<Object>{ String.valueOf(quoteId), String.valueOf(lineItemId) };
    }

    private static Id getLineItemRecordId(Map<String, Object> lineItem) {
        String lineItemId = (String) lineItem.get('_recordId');
        if (String.isBlank(lineItemId)) {
            return null;
        }
        try {
            return Id.valueOf(lineItemId);
        } catch (Exception e) {
            return null;
        }
    }
}

/**
 * @description Stamps renewal quote header fields when platform Asset Renew creates a bare quote.
 *              Copies commercial / routing fields from the source order's quote on the contract
 *              (Renewal_Contract__c, Legal Entity, partner, places, opportunity, etc.).
 */
public with sharing class RenewalQuoteHeaderHandler {

    @TestVisible
    private static Map<Id, Id> testSourceQuoteIdByContractId;

    public static void applyRenewalQuoteHeaders(List<Quote> quotes) {
        if (quotes == null || quotes.isEmpty()) {
            return;
        }

        Map<Id, Quote> quotesByContractId = new Map<Id, Quote>();
        for (Quote quote : quotes) {
            if (!isRenewalQuoteContext(quote)) {
                continue;
            }

            Id contractId = resolveContractId(quote);
            if (contractId == null) {
                continue;
            }

            if (quote.Renewal_Contract__c == null) {
                quote.Renewal_Contract__c = contractId;
            }

            quotesByContractId.put(contractId, quote);
        }

        if (quotesByContractId.isEmpty()) {
            return;
        }

        Map<Id, Quote> sourceQuotesByContractId = loadSourceQuotesByContractId(quotesByContractId.keySet());
        for (Id contractId : quotesByContractId.keySet()) {
            Quote sourceQuote = sourceQuotesByContractId.get(contractId);
            if (sourceQuote == null) {
                continue;
            }
            stampHeaderFields(quotesByContractId.get(contractId), sourceQuote);
        }
    }

    @TestVisible
    private static Boolean isRenewalQuoteContext(Quote quote) {
        return quote != null && (
            quote.OriginalActionType == QuoteRenewalTypeHandler.ORIGINAL_ACTION_RENEW
            || quote.Quote_Type__c == QuoteRenewalTypeHandler.QUOTE_TYPE_RENEWAL
        );
    }

    @TestVisible
    private static Id resolveContractId(Quote quote) {
        if (quote == null) {
            return null;
        }
        if (quote.Renewal_Contract__c != null) {
            return quote.Renewal_Contract__c;
        }
        return quote.ContractId;
    }

    @TestVisible
    private static Map<Id, Quote> loadSourceQuotesByContractId(Set<Id> contractIds) {
        Map<Id, Quote> sourceQuotesByContractId = new Map<Id, Quote>();
        if (contractIds == null || contractIds.isEmpty()) {
            return sourceQuotesByContractId;
        }

        Map<Id, Id> sourceQuoteIdByContractId = resolveSourceQuoteIdByContractId(contractIds);
        Set<Id> sourceQuoteIds = new Set<Id>(sourceQuoteIdByContractId.values());
        if (sourceQuoteIds.isEmpty()) {
            return sourceQuotesByContractId;
        }

        Map<Id, Quote> sourceQuotesById = new Map<Id, Quote>(querySourceQuotes(sourceQuoteIds));
        for (Id contractId : sourceQuoteIdByContractId.keySet()) {
            Quote sourceQuote = sourceQuotesById.get(sourceQuoteIdByContractId.get(contractId));
            if (sourceQuote != null) {
                sourceQuotesByContractId.put(contractId, sourceQuote);
            }
        }
        return sourceQuotesByContractId;
    }

    private static Map<Id, Id> resolveSourceQuoteIdByContractId(Set<Id> contractIds) {
        Map<Id, Id> sourceQuoteIdByContractId = new Map<Id, Id>();

        if (Test.isRunningTest() && testSourceQuoteIdByContractId != null) {
            for (Id contractId : contractIds) {
                if (testSourceQuoteIdByContractId.containsKey(contractId)) {
                    sourceQuoteIdByContractId.put(contractId, testSourceQuoteIdByContractId.get(contractId));
                }
            }
            return sourceQuoteIdByContractId;
        }

        for (Contract contract : [
            SELECT Id, SourceQuoteId
            FROM Contract
            WHERE Id IN :contractIds
              AND SourceQuoteId != null
        ]) {
            sourceQuoteIdByContractId.put(contract.Id, contract.SourceQuoteId);
        }

        Set<Id> contractsWithoutSource = new Set<Id>();
        for (Id contractId : contractIds) {
            if (!sourceQuoteIdByContractId.containsKey(contractId)) {
                contractsWithoutSource.add(contractId);
            }
        }

        if (!contractsWithoutSource.isEmpty()) {
            for (Order sourceOrder : [
                SELECT ContractId, QuoteId
                FROM Order
                WHERE ContractId IN :contractsWithoutSource
                  AND QuoteId != null
                ORDER BY CreatedDate DESC
            ]) {
                if (!sourceQuoteIdByContractId.containsKey(sourceOrder.ContractId)) {
                    sourceQuoteIdByContractId.put(sourceOrder.ContractId, sourceOrder.QuoteId);
                }
            }
        }

        return sourceQuoteIdByContractId;
    }

    private static List<Quote> querySourceQuotes(Set<Id> sourceQuoteIds) {
        return [
            SELECT Id,
                   OpportunityId,
                   LegalEntityId,
                   SalesTransactionTypeId,
                   ContactId,
                   BillToContactId,
                   Bill_To_Place__c,
                   Ship_To_Place__c,
                   Primary_Place__c,
                   End_User_Place__c,
                   Install_Place__c,
                   Service_Place__c,
                   Regulatory_Place__c,
                   Partner_Place__c,
                   Billing_Partner__c,
                   PartnerAccountId,
                   Partner_Pricing_Model__c,
                   Deal_Type__c,
                   Reseller__c,
                   Distributor__c,
                   Referral_Partner__c,
                   Net_Terms__c,
                   Language__c,
                   Payment_Portal__c,
                   CurrencyIsoCode,
                   BillingStreet,
                   BillingCity,
                   BillingState,
                   BillingPostalCode,
                   BillingCountry,
                   BillingStateCode,
                   BillingCountryCode,
                   ShippingStreet,
                   ShippingCity,
                   ShippingState,
                   ShippingPostalCode,
                   ShippingCountry,
                   ShippingStateCode,
                   ShippingCountryCode,
                   QuoteToStreet,
                   QuoteToCity,
                   QuoteToState,
                   QuoteToPostalCode,
                   QuoteToCountry,
                   QuoteToStateCode,
                   QuoteToCountryCode
            FROM Quote
            WHERE Id IN :sourceQuoteIds
        ];
    }

    @TestVisible
    private static void stampHeaderFields(Quote target, Quote source) {
        if (target == null || source == null) {
            return;
        }

        copyIdIfBlank(target, source, 'OpportunityId');
        copyIdIfBlank(target, source, 'LegalEntityId');
        copyIdIfBlank(target, source, 'SalesTransactionTypeId');
